// Generated by Suite Builder from a crawl of the site. The link report: every address the crawl requested, asked again
// (LinkReportTest).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The addresses are the crawl's: suite build writes
// them, in src/test/resources/link-report/.
package com.spiralmm.tests.core;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import java.util.function.ToIntFunction;

/**
 * The link report: every address the crawl requested, asked once more by HTTP, what it
 * answers now beside what it answered then, in target/link-report.md. One that answered 2xx in the
 * crawl and does not now is broken since: LinkReportTest fails on it. One already broken in the
 * crawl is listed as known, never failed again; the rest are listed as fine.
 */
public final class LinkReport {
    public static final Path REPORT = Path.of("target", "link-report.md");
    /**
     * The addresses, written by Suite Builder from the crawl: path, status then ("-": no answer), pages linking to it.
     */
    private static final String LINKS = "/link-report/links.tsv";

    private LinkReport() {}

    /**
     * First each address the site's name points to (Addresses): none taking a connection, the site
     * cannot be reached, and the failure says so in the words StopEarly stops the run on; some taking
     * none, the site's own defect (SITE-06), said with each, and the run goes on: which address each test
     * is given decides whether it waits, so the links are not asked. Then every address the crawl
     * requested ({@code statusOf}: its status now; a failure counts as no answer), one after another and
     * with the suite's pause between them (-DtestDelay); writes the report and returns what is broken
     * since the crawl, one sentence each. When the first gets no answer at all, the rest are not asked,
     * each waiting out its timeout.
     */
    public static List<String> check(ToIntFunction<String> statusOf) {
        List<String[]> links = read();
        Addresses.Found site = Addresses.of(SiteConfig.baseUrl());
        if (site != null) {
            StepLog.step("Try each address " + site.host() + " points to ("
                    + (site.all().isEmpty() ? "none found" : String.join(", ", site.all())) + ")");
            if (site.noneAnswer()) {
                new Rows(INTERNAL).write(REPORT, INTRO);
                throw new Addresses.Settled("The site cannot be reached: "
                        + (site.unresolved().isEmpty() ? "none of the " + site.all().size() + " addresses "
                        + site.host()
                        + " points to takes a connection" : site.unresolved()) + "; the " + links.size()
                                + " addresses the crawl requested were not asked", null);
            }
            if (site.someDead()) {
                new Rows(INTERNAL).write(REPORT, INTRO);
                // Filed as a bug by the build (bugs/open/SITE-06.md): while it is open, this test is blocked by it, not
                // failed.
                if (KnownBugs.open("SITE-06")) throw KnownBugs.blocked("SITE-06", site.deadSaid() + "; the "
                        + links.size() + " addresses the crawl requested were not asked. The other tests run.");
                throw new Addresses.Settled(site.deadSaid()
                        + ": the site's own defect (SITE-06, KNOWN-ISSUES.md): a visitor given it waits, and one given "
                        + "another does not."
                        + " The " + links.size()
                                + " addresses the crawl requested were not asked: each would take whichever address it "
                                + "was given. The other tests run.", null);
            }
        }
        if (site != null && KnownBugs.open("SITE-06")) KnownBugs.looksFixed("SITE-06", "each address " + site.host()
                + " points to took a connection");
        StepLog.step("Ask the " + links.size() + " addresses the crawl requested, once each (" + REPORT + ")");
        List<String> since = new ArrayList<>();
        Rows rows = new Rows(INTERNAL);
        for (String[] link : links) {
            Pace.betweenRequests();
            int now;
            try {
                now = statusOf.applyAsInt(link[0]);
            } catch (RuntimeException | AssertionError e) {
                if (rows.none()) {
                    rows.add(1, link[0], said(link[1].equals("-") ? 0 : Integer.parseInt(link[1])), "no answer",
                            link[2]);
                    rows.write(REPORT, INTRO);
                    throw new AssertionError(link[0] + " gave no answer (" + e.getMessage() + "); the other "
                            + (links.size() - 1) + " addresses were not asked");
                }
                now = 0;
            }
            int then = link[1].equals("-") ? 0 : Integer.parseInt(link[1]);
            rows.add(ok(then) && !ok(now) ? 0 : ok(then) ? 2 : 1, link[0], said(then), said(now), link[2]);
            if (ok(then) && !ok(now)) since.add(link[0] + " answered " + said(now) + " (" + then + " in the crawl)");
        }
        rows.write(REPORT, INTRO);
        return since;
    }

    private static final String[] INTERNAL = {"Broken since the crawl", "Broken in the crawl, still listed",
            "Answering as in the crawl"};
    private static final String INTRO =
            "# Link report\n\nEvery address the crawl requested, asked again by this run. One that answered in the "
            + "crawl\n"
            + "and does not now fails LinkReportTest; one already broken in the crawl is listed as known.\n";
    /**
     * The links to other sites, written by Suite Builder from the crawl: address, status then, how it was judged
     * (alive, barred, broken), pages linking to it.
     */
    private static final String EXTERNAL = "/link-report/external.tsv";
    public static final Path EXTERNAL_REPORT = Path.of("target", "external-link-report.md");

    /** One request's answer, no redirect followed: its status, and the Location it names ("" for none). */
    public record Hop(int status, String location) {}

    /**
     * Every link to another site the crawl got an answer from, asked once more ({@code once}: one request, no
     * redirect followed; a failure counts as no answer). Redirects are followed here, one at a time, and none is
     * sent further in than the site under test: a public site's link, or a redirect of it, into a private network,
     * this computer or a cloud machine's credentials (169.254.169.254) is not asked, and the report says why. A
     * server error or no answer is asked again after the rest. Gone: 400 or more, or no answer; but a site keeping
     * test tools out (401, 403, 429, 999) is never judged, and when example.com (IANA keeps it up for good) gives
     * no answer either, no link without one is called gone: the network, not the sites. Writes
     * target/external-link-report.md and returns each link that answered in the crawl and is gone now.
     */
    public static List<String> checkExternal(Function<String, Hop> once) {
        List<String[]> links = read(EXTERNAL, 4);
        StepLog.step("Ask the " + links.size() + " links to other sites, once each (" + EXTERNAL_REPORT + ")");
        int site = depthOf(SiteConfig.baseUrl());
        int[] now = new int[links.size()];
        String[] notAsked = new String[links.size()];
        for (int pass = 0; pass < 2; pass++) {
            for (int i = 0; i < links.size(); i++) if (pass == 0
                    || (notAsked[i] == null && (now[i] == 0 || now[i] >= 500))) now[i] = ask(once, links.get(i)[0],
                    site, notAsked, i);
        }
        boolean cut = Arrays.stream(now).anyMatch(n -> n == 0)
                && ask(once, "https://example.com/", site, new String[1], 0) == 0;
        List<String> since = new ArrayList<>();
        Rows rows = new Rows("Gone since the crawl", "Broken in the crawl, still listed",
                "Keeping test tools out (401, 403, 429, 999): not judged",
                "No answer, and example.com gave none either: this computer's network, not judged", "Answering",
                "Leading further in than the site under test (a private network, this computer): not asked");
        for (int i = 0; i < links.size(); i++) {
            String[] link = links.get(i);
            boolean gone = now[i] == 0 || now[i] >= 400;
            int section = notAsked[i] != null ? 5 : now[i] == 0 && cut ? 3 : link[2].equals("barred")
                    || List.of(401, 403, 429, 999).contains(now[i]) ? 2 : link[2].equals("broken") ? 1 : gone ? 0 : 4;
            rows.add(section, link[0], link[1], notAsked[i] != null ? notAsked[i] : said(now[i]), link[3]);
            if (section == 0) since.add(link[0] + (now[i] == 0 ? " gave no answer" : " answered " + now[i]) + " ("
                    + link[1] + " in the crawl), linked from " + link[3]);
        }
        rows.write(EXTERNAL_REPORT,
                "# Links to other sites\n\nEvery link to another site the crawl got an answer from, asked again by "
                + "this run. One that\n"
                + "answered in the crawl and is gone now (400 or more, or no answer twice) fails LinkReportTest.\n");
        return since;
    }

    /**
     * A link's status, its redirects followed hop by hop; 0 for no answer, or for a hop further in than the site, said
     * in {@code notAsked[i]}.
     */
    private static int ask(Function<String, Hop> once, String first, int site, String[] notAsked, int i) {
        Pace.betweenRequests();
        String url = first;
        try {
            for (int hop = 0; ; hop++) {
                int to = depthOf(url);
                if (to == 3 || to > site) {
                    notAsked[i] = "not asked: " + url + " leads to " + FURTHER[to]
                            + ", further in than the site under test";
                    return 0;
                }
                Hop answer = once.apply(url);
                if (answer.status() < 300 || answer.status() > 399 || answer.location() == null || answer.location()
                        .isBlank() || hop >= 20) return answer.status();
                url = URI.create(url).resolve(answer.location()).toString();
            }
        } catch (RuntimeException | AssertionError e) {
            return 0;
        }
    }

    private static final String[] FURTHER = {"the internet", "a private network", "this computer",
            "an address no page should lead to (link-local, where a cloud machine keeps its credentials)"};

    /**
     * How far in a URL's host leads: 0 the internet, 1 a private network, 2 this computer, 3 nowhere a page should; a
     * name not found, 0.
     */
    static int depthOf(String url) {
        String host = URI.create(url).getHost();
        if (host == null) return 0;
        host = host.replaceAll("^\\[|\\]$", "").toLowerCase();
        if (host.equals("localhost") || host.endsWith(".localhost")) return 2;
        int deepest = 0;
        try {
            for (InetAddress address : InetAddress.getAllByName(host)) deepest = Math.max(deepest, depthOf(address));
        } catch (IOException e) {
            return 0;
        }
        return deepest;
    }

    /**
     * The IANA special-purpose IPv4 blocks, most specific first (base, prefix length, depth): documentation and
     * benchmarking lead nowhere a page should. The same rule as the crawl that built this suite.
     */
    private static final long[][] V4 = {{0L, 8, 3}, {2130706432L, 8, 2}, {2851995648L, 16, 3}, {3221225472L, 24, 3},
            {3221225984L, 24, 3},
            {3227017984L, 24, 3}, {3323068416L, 15, 3}, {3325256704L, 24, 3}, {3405803776L, 24, 3},
                    {3758096384L, 3, 3}, {167772160L, 8, 1},
            {2886729728L, 12, 1}, {3232235520L, 16, 1}, {1681915904L, 10, 1}};

    /**
     * The special IPv6 blocks, most specific first (first groups, prefix length, depth); outside 2000::/3 nothing is
     * public.
     */
    private static final int[][] V6 = {{0x64, 0xff9b, 1, 48, 3}, {0x100, 64, 3}, {0x2001, 2, 48, 3},
            {0x2001, 0x10, 28, 3}, {0x2001, 0x20, 28, 3},
            {0x2001, 0xdb8, 32, 3}, {0x3fff, 20, 3}, {0x5f00, 16, 3}, {0xfe80, 10, 3}, {0xfec0, 10, 1}, {0xfc00, 7, 1},
                    {0xff00, 8, 3}};

    private static int four(long n) {
        for (long[] block : V4) if (n >>> (32 - block[1]) == block[0] >>> (32 - block[1])) return (int) block[2];
        return 0;
    }

    /**
     * How far in one address leads. One carrying an IPv4 address (mapped, compatible, SIIT, NAT64, 6to4, Teredo's
     * client) leads where it does.
     */
    static int depthOf(InetAddress a) {
        byte[] b = a.getAddress();
        if (b.length == 4) return four(
                ((b[0] & 0xffL) << 24) | ((b[1] & 0xffL) << 16) | ((b[2] & 0xffL) << 8) | (b[3] & 0xffL));
        int[] g = new int[8];
        for (int i = 0; i < 8; i++) g[i] = ((b[2 * i] & 0xff) << 8) | (b[2 * i + 1] & 0xff);
        if (zero(g, 0, 8)) return 3;
        if (zero(g, 0, 7) && g[7] == 1) return 2;
        if ((zero(g, 0, 5) && g[5] == 0xffff) || zero(g, 0, 6)
                || (zero(g, 0, 4) && g[4] == 0xffff && g[5] == 0)) return four(((long) g[6] << 16) | g[7]);
        if (g[0] == 0x64 && g[1] == 0xff9b && zero(g, 2, 6)) return four(((long) g[6] << 16) | g[7]);
        if (g[0] == 0x2002) return four(((long) g[1] << 16) | g[2]);
        if (g[0] == 0x2001 && g[1] == 0) return four(((long) (g[6] ^ 0xffff) << 16) | (g[7] ^ 0xffff));
        for (int[] block : V6) {
            int bits = block[block.length - 2];
            boolean in = true;
            for (int i = 0; i < bits && in; i++) {
                int base = i / 16 < block.length - 2 ? block[i / 16] : 0;
                in = ((g[i / 16] >> (15 - i % 16)) & 1) == ((base >> (15 - i % 16)) & 1);
            }
            if (in) return block[block.length - 1];
        }
        return (g[0] & 0xe000) == 0x2000 ? 0 : 3;
    }

    private static boolean zero(int[] g, int from, int to) {
        for (int i = from; i < to; i++) if (g[i] != 0) return false;
        return true;
    }

    private static boolean ok(int status) {
        return status >= 200 && status < 300;
    }

    private static String said(int status) {
        return status == 0 ? "no answer" : String.valueOf(status);
    }

    private static List<String[]> read() {
        return read(LINKS, 3);
    }

    /** A file's rows of {@code cells} cells, the last the pages linking to it, said with commas. */
    private static List<String[]> read(String file, int cells) {
        List<String[]> out = new ArrayList<>();
        InputStream in = LinkReport.class.getResourceAsStream(file);
        if (in == null) throw new IllegalStateException(file
                + " is missing: rebuild the suite (suite build <project>) to put it back.");
        try (BufferedReader lines = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            for (String line = lines.readLine(); line != null; line = lines.readLine()) {
                if (line.isBlank() || line.startsWith("#")) continue;
                String[] row = Arrays.copyOf((line + "\t".repeat(cells)).split("\t", -1), cells);
                row[cells - 1] = row[cells - 1].replace(" ", ", ");
                out.add(row);
            }
        } catch (IOException e) {
            throw new IllegalStateException("could not read " + file + ": " + e.getMessage(), e);
        }
        return out;
    }

    /** A report's sections, each a title and its rows, written as Markdown tables. */
    private static final class Rows {
        private final String[] titles;
        private final List<List<String>> rows = new ArrayList<>();

        Rows(String... titles) {
            this.titles = titles;
            for (String t : titles) rows.add(new ArrayList<>());
        }

        boolean none() {
            return rows.stream().allMatch(List::isEmpty);
        }

        void add(int section, String address, String then, String now, String from) {
            rows.get(section).add("| " + address + " | " + then + " | " + now + " | " + from + " |");
        }

        void write(Path file, String intro) {
            StringBuilder md = new StringBuilder(intro);
            for (int i = 0; i < titles.length; i++) {
                md.append("\n## ").append(titles[i]).append(" (").append(rows.get(i).size()).append(")\n\n");
                if (rows.get(i).isEmpty()) md.append("None.\n");
                else md.append("| Address | In the crawl | Now | Linked from |\n| --- | --- | --- | --- |\n")
                        .append(String.join("\n", rows.get(i))).append('\n');
            }
            try {
                Files.createDirectories(file.getParent());
                Files.writeString(file, md.toString(), StandardCharsets.UTF_8);
            } catch (IOException e) {
                System.out.println("   note: could not write " + file + ": " + e.getMessage());
            }
        }
    }
}
